/* cppi::3d95ce8e1e2774e5d303e1b48e9362f74874977138ff526b71a1f814643ffec7 */
select business_date as date_, security_id, 'EUGBR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-25' and business_date <= date '2025-06-25' and weight_ndo>0 and id_cppib_index = 'EUGBR_GR_USD_0_0' and security_id is not null

/* cppi::50892fa8292836b3419abdf5232652954f837c9dea4123c14c9e5662706faab8 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-04-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-04-01'
    ) a
where arrival_time = max_publish

